  /** region-description case: {stemEn, stemMs, descEn, descMs} */
  /** worked solution for a region-description case. */
  const regW = (c) => W(T('Turn the condition into a standard locus, then read the boundary from the words: "at most"/"at least" include it, "less than"/"more than" exclude it.', 'Tukar syarat itu kepada lokus piawai, kemudian baca sempadannya daripada perkataannya: "selebih-lebihnya"/"sekurang-kurangnya" termasuk, "kurang daripada"/"lebih daripada" tidak termasuk.'), T(c.descEn, c.descMs), T(c.boundEn, c.boundMs));
